insert into public.policy_documents (doc_id, title, summary) values ($md$damaged_or_defective$md$, $md$Damaged and Defective Items Policy$md$, $md$What to do when a customer reports an item that arrived damaged or stopped working.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$damaged_or_defective$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$damaged_or_defective$md$, $md$Within 30 days of purchase$md$, $md$Offer a replacement or a full refund, at the customer's choice. This applies to all categories, including electronics and final sale items.

Ask the customer to bring the item and all accessories. Fill out a Damaged Item Report in the POS before processing the replacement or refund.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$damaged_or_defective$md$, $md$After 30 days$md$, $md$Defects after 30 days are covered by the manufacturer's warranty, not by NovaMart. Give the customer the manufacturer's support contact printed on the product manual or packaging.

Exception: products sold with a NovaMart Protection Plan are handled by the Protection Plan desk (extension 4400) at any time during the plan.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$damaged_or_defective$md$, $md$Large appliances and furniture delivered to the home$md$, $md$Visible delivery damage must be reported within 48 hours of delivery. Ask the customer to send photos to the store email. After 48 hours, the case is treated as a standard defect claim.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$damaged_or_defective$md$, $md$Photos and documentation$md$, $md$Always attach at least one photo of the damage to the Damaged Item Report. Reports without photos are rejected by the returns center and the store absorbs the cost.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$damaged_or_defective$md$, $md$Suspected misuse or fraud$md$, $md$If the damage looks like misuse (water damage, cracked screen with no packaging damage, missing serial number), do not refuse the customer directly. Escalate to the store manager and to the Operations helpdesk with the report number.$md$, 4);

insert into public.policy_documents (doc_id, title, summary) values ($md$delivery_and_order_tracking$md$, $md$Delivery and Order Tracking$md$, $md$How to look up an order, what each status means, and what to tell the customer.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$delivery_and_order_tracking$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$delivery_and_order_tracking$md$, $md$Looking up an order$md$, $md$Use the order lookup tool with the order number (format NM-#### printed on the confirmation email). Never guess an order's status from memory. The lookup returns the current status, the carrier, the estimated delivery date and the last tracking event.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$delivery_and_order_tracking$md$, $md$Delivery times$md$, $md$Standard shipping: 3 to 5 business days after the order ships. Express shipping: 1 to 2 business days. Store pickup orders are ready within 2 hours during store opening times, and held for 7 days.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$delivery_and_order_tracking$md$, $md$Order statuses and what to tell the customer$md$, $md$- Processing: the order was received and is being prepared. Tell the customer it will ship within 1 business day.
- Shipped or In transit: the carrier has the package. Share the carrier and tracking number.
- Delayed: the carrier reported a delay. Apologize, share the new estimated date, and offer a 10 dollar NovaPoints credit (1,000 points) for the inconvenience. No approval is needed for this credit.
- Delivered: the carrier confirmed delivery. If the customer says they did not receive it, follow the missing package procedure.
- Cancelled: the order was cancelled. Refunds for cancelled orders are issued automatically within 5 business days.
- Return in progress: the customer sent the item back. Refund is issued after the returns center inspects the item, usually 3 to 5 business days after arrival.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$delivery_and_order_tracking$md$, $md$Missing package procedure$md$, $md$If the status is Delivered but the customer did not receive the package:

1. Ask the customer to check with neighbors, building reception and the carrier's delivery photo if available.
2. If the package is still missing 48 hours after the delivery timestamp, file a Missing Package Claim in the POS. The claim triggers a replacement or refund within 3 business days.
3. Claims above 300 dollars are reviewed by the Operations team before approval.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$delivery_and_order_tracking$md$, $md$Changing or cancelling an order$md$, $md$Orders can be cancelled by the customer or by a store employee while the status is Processing. Once the status is Shipped, the order cannot be cancelled; the customer can refuse delivery or return the item after it arrives.$md$, 4);

insert into public.policy_documents (doc_id, title, summary) values ($md$escalation_and_contacts$md$, $md$Escalation and Contacts$md$, $md$When a store employee must escalate, and who to contact.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$escalation_and_contacts$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$escalation_and_contacts$md$, $md$Operations helpdesk$md$, $md$The Operations helpdesk handles questions that are not covered by the policies, system errors in the POS, and approvals above the store manager's limits.

- Hours: Monday to Saturday, 8:00 to 20:00 (store local time).
- Channel: ticket through this assistant or the Ops Portal. Phone (extension 4000) only for issues blocking a sale in progress.
- Target response time: 2 hours for blocking issues, 1 business day for everything else.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$escalation_and_contacts$md$, $md$When to escalate to the store manager$md$, $md$- Refunds above 500 dollars.
- Price match differences above 100 dollars.
- Any suspected fraud or misuse.
- Customer complaints about employee behavior.
- Any situation where the customer asks to speak to a manager.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$escalation_and_contacts$md$, $md$When to escalate to the Operations team$md$, $md$- Missing package claims above 300 dollars.
- Questions not covered by any policy document.
- Requests for exceptions to a policy (for example, a return outside the window).
- POS errors that prevent a return, refund or price match from being processed.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$escalation_and_contacts$md$, $md$What to include in an escalation$md$, $md$Store number, order number (if any), a one-line summary of the customer's request, what policy was checked, and what the customer was told so far. Escalations without this information are sent back to the store.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$escalation_and_contacts$md$, $md$Human Resources, payroll and scheduling$md$, $md$Questions about pay, benefits, shifts and time off are not handled by Operations. Employees should use the HR Portal or call HR at extension 2000.$md$, 4);

insert into public.policy_documents (doc_id, title, summary) values ($md$exchanges$md$, $md$Exchanges Policy$md$, $md$How to handle exchanges for size, color, model or a different product.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$exchanges$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$exchanges$md$, $md$Exchange window$md$, $md$Exchanges follow the same window as returns: 30 days for most products and 15 days for electronics. The holiday extension also applies.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$exchanges$md$, $md$Same product, different size or color$md$, $md$Exchange at no cost if the new item has the same price. No manager approval is needed.

If the new size or color is out of stock in the store, offer one of these options:

- Check stock in nearby stores and reserve the item for pickup.
- Place a ship-to-home order at the same price, free shipping.
- Process a return and refund.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$exchanges$md$, $md$Different product$md$, $md$Process the exchange as a return followed by a new sale. The customer pays the difference if the new item costs more, or receives the difference back to the original payment method if it costs less.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$exchanges$md$, $md$Items that cannot be exchanged$md$, $md$The same final sale rules from the Returns and Refunds Policy apply. Final sale items cannot be exchanged.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$exchanges$md$, $md$Exchange without receipt$md$, $md$Same-product exchanges for size or color can be done without a receipt if the item is clearly a NovaMart product with an intact tag. Any other exchange without proof of purchase follows the no-receipt rule in the Returns and Refunds Policy (store credit at the lowest price in the last 90 days).$md$, 4);

insert into public.policy_documents (doc_id, title, summary) values ($md$gift_cards_and_store_credit$md$, $md$Gift Cards and Store Credit$md$, $md$Rules for selling, redeeming and replacing gift cards and store credit.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$gift_cards_and_store_credit$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$gift_cards_and_store_credit$md$, $md$Gift cards$md$, $md$- Gift cards are sold in amounts from 10 to 500 dollars. They never expire.
- Gift cards cannot be redeemed for cash, except where state law requires cash back for small remaining balances (under 10 dollars in most states; check the state list in the POS).
- Gift cards cannot be used to buy other gift cards.
- Gift cards cannot be returned or refunded once activated.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$gift_cards_and_store_credit$md$, $md$Lost or stolen gift cards$md$, $md$A gift card can only be replaced if the customer has the original purchase receipt or the card number. Replace the remaining balance on a new card. Without receipt or card number, the card cannot be replaced.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$gift_cards_and_store_credit$md$, $md$Store credit$md$, $md$Store credit is issued as a NovaMart Credit Card (a physical or digital card) for no-receipt returns and some refunds.

- Store credit expires 12 months after it is issued.
- Store credit can be used in any NovaMart store or on novamart.com.
- Store credit cannot be converted to cash.
- Store credit balance can be checked at any register with the card number.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$gift_cards_and_store_credit$md$, $md$Partial payments$md$, $md$A purchase can combine a gift card or store credit with any other payment method. Apply the gift card or store credit first, then the remaining balance.$md$, 3);

insert into public.policy_documents (doc_id, title, summary) values ($md$loyalty_program$md$, $md$NovaPoints Loyalty Program$md$, $md$How customers earn and use NovaPoints, and how to handle common questions at the register.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$loyalty_program$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$loyalty_program$md$, $md$Earning points$md$, $md$Members earn 1 point per dollar spent, before tax, on all purchases except gift cards. 500 points are worth 5 dollars.

Points appear in the account within 24 hours of the purchase. Online orders earn points when the order ships.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$loyalty_program$md$, $md$Enrolling a customer$md$, $md$Enrollment is free and takes one minute at any register or on novamart.com. The customer needs a phone number and an email address. Points from the current purchase can be added if the customer enrolls before paying.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$loyalty_program$md$, $md$Using points$md$, $md$Points can be redeemed at checkout in multiples of 500 (5 dollars). Points cannot be redeemed for cash, gift cards or shipping fees.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$loyalty_program$md$, $md$Points and returns$md$, $md$When an item is returned, the points earned on that item are deducted from the account. If the account does not have enough points, the deduction is applied to the refund amount.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$loyalty_program$md$, $md$Expiration$md$, $md$Points expire after 18 months without any purchase on the account. A purchase of any amount resets the counter.$md$, 4);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$loyalty_program$md$, $md$Missing points$md$, $md$If points are missing from a purchase, the customer can present the receipt at any register within 60 days and the cashier can add the points manually. After 60 days, the request goes to the Operations helpdesk.$md$, 5);

insert into public.policy_documents (doc_id, title, summary) values ($md$price_match$md$, $md$Price Match Policy$md$, $md$When and how NovaMart matches a competitor's price.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$price_match$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$price_match$md$, $md$Who we match$md$, $md$We match the current advertised price of these retailers: Target, Walmart, Best Buy, Costco (members' price), and Amazon only for items sold and shipped by Amazon itself.

We do not match third-party marketplace sellers (including Amazon Marketplace, eBay and Walmart Marketplace), auction sites, membership-only flash sales, or prices that require a coupon code.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$price_match$md$, $md$Conditions$md$, $md$- The item must be identical: same brand, model number, color and size.
- The competitor must have the item in stock at the time of the request.
- The competitor's price must be shown on their official website or printed ad. A screenshot from a search engine is not enough; open the product page.
- The price match is per item, limited to one unit per customer per day.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$price_match$md$, $md$Timing$md$, $md$Price matches can be requested at the time of purchase or up to 14 days after the purchase. After the purchase, the customer must present the receipt and the difference is refunded to the original payment method.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$price_match$md$, $md$Exclusions$md$, $md$No price match on clearance, open-box, refurbished items, Black Friday week (the Monday before Thanksgiving through Cyber Monday), doorbuster deals, bundle offers, or items sold by NovaMart Marketplace sellers.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$price_match$md$, $md$Approval$md$, $md$Price matches up to 100 dollars in difference can be approved by any cashier. Above 100 dollars, a shift lead or manager must approve.$md$, 4);

insert into public.policy_documents (doc_id, title, summary) values ($md$returns_and_refunds$md$, $md$Returns and Refunds Policy$md$, $md$Rules for accepting returns and issuing refunds in NovaMart stores. Applies to purchases made in store and on novamart.com.$md$)
  on conflict (doc_id) do update set title = excluded.title, summary = excluded.summary, updated_at = now();
delete from public.policy_sections where doc_id = $md$returns_and_refunds$md$;
insert into public.policy_sections (doc_id, heading, body, position) values ($md$returns_and_refunds$md$, $md$Standard return window$md$, $md$Most products can be returned within 30 days of the purchase date, in original condition and with original packaging.

Electronics (TVs, laptops, tablets, phones, headphones, cameras and gaming consoles) have a shorter window: 15 days from the purchase date.

The purchase date is the date printed on the receipt. For online orders, it is the delivery date shown in the order record.$md$, 0);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$returns_and_refunds$md$, $md$Holiday extension$md$, $md$Purchases made between November 1 and December 24 can be returned until January 15 of the following year. The holiday extension applies to all categories, including electronics.$md$, 1);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$returns_and_refunds$md$, $md$Proof of purchase$md$, $md$A receipt, an order number or the card used for payment is accepted as proof of purchase. Look up online orders by order number.

Without proof of purchase, the item can only be returned for store credit at the lowest price the item sold for in the last 90 days, and only with a valid photo ID. Record the ID number in the return form.$md$, 2);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$returns_and_refunds$md$, $md$Refund method$md$, $md$Refunds go back to the original payment method:

- Credit or debit card: 5 to 10 business days to appear on the statement.
- Cash: refunded in cash up to 200 dollars. Above that, a check is mailed within 10 business days.
- Gift card or store credit: refunded as store credit.

Refunds above 500 dollars require a manager's approval before processing.$md$, 3);
insert into public.policy_sections (doc_id, heading, body, position) values ($md$returns_and_refunds$md$, $md$Items that cannot be returned$md$, $md$The following items are final sale and cannot be returned or exchanged:

- Clearance items marked "Final Sale" on the price tag or receipt.
- Opened software, video games, music and movies.
- Personal care items that have been opened (razors, toothbrushes, cosmetics).
- Underwear, swimwear and earrings, for hygiene reasons.
- Custom or personalized products.
- Gift cards.

Items that are damaged or defective follow the Damaged and Defective Items policy, even if they are in a final sale category.$md$, 4);

